// Some portions generated by Claude

/**
 * Copies text by selecting it in a hidden text area, for when the browser offers no clipboard: it has none on a page
 * served over plain HTTP other than localhost, where many Workbenches run. Focus returns to the control that asked.
 */
function copyThroughSelection(text: string, doc: Document): boolean {
  if (!doc.body || typeof doc.execCommand !== "function") {
    return false;
  }
  const focused = doc.activeElement as HTMLElement | null;
  const area = doc.createElement("textarea");
  area.value = text;
  area.setAttribute("readonly", "");
  area.setAttribute("aria-hidden", "true");
  Object.assign(area.style, { position: "fixed", top: "0", left: "0", opacity: "0", pointerEvents: "none" });
  doc.body.appendChild(area);
  try {
    area.select();
    return doc.execCommand("copy") === true;
  } catch {
    return false;
  } finally {
    area.remove();
    focused?.focus?.();
  }
}

/**
 * Copies text to the clipboard; without one, or when it refuses, through a selection. Fails when nothing could copy,
 * so the page can say how to copy instead.
 */
export async function copyToClipboard(text: string, doc: Document = document): Promise<void> {
  const clipboard = doc.defaultView?.navigator?.clipboard;
  if (clipboard && typeof clipboard.writeText === "function") {
    try {
      await clipboard.writeText(text);
      return;
    } catch {
      // Refused: the selection may still copy.
    }
  }
  if (!copyThroughSelection(text, doc)) {
    throw new Error("Nothing could copy the text");
  }
}
